from __future__ import annotations
import hashlib,json
from typing import Any,Mapping,Sequence
from .gtm_all_subvertical_unified_review_v2 import validate_unified_review_intake
from .gtm_case_evidence_funnel_v2 import build_case_evidence_funnel_standard,compile_case_evidence_funnel_coverage

ADMISSION_SCHEMA="ProofLaunchGTMRightMessageCaseCandidateAdmissionV2"; CASE_ID="case-rightmessage-2017-2026-launch-failure-rebuild-turnaround"
class GTMRightMessageCandidateAdmissionError(ValueError): pass
def _canonical(value:Any)->str: return json.dumps(value,ensure_ascii=False,sort_keys=True,separators=(",",":"),allow_nan=False)
def _digest(value:Any)->str: return hashlib.sha256(_canonical(value).encode()).hexdigest()
def _seal(payload:Mapping[str,Any],label:str)->None:
    unsigned=dict(payload); supplied=unsigned.pop("content_sha256",None)
    if supplied!=_digest(unsigned): raise GTMRightMessageCandidateAdmissionError(f"{label} seal is invalid")
def compile_rightmessage_candidate_admission(intake:Mapping[str,Any],ledger:Mapping[str,Any],dossier:Mapping[str,Any],proposal:Mapping[str,Any],existing_candidates:Sequence[Mapping[str,Any]]=())->dict[str,Any]:
    validate_unified_review_intake(intake,ledger); _seal(dossier,"RightMessage dossier"); _seal(proposal,"RightMessage proposal")
    if dossier.get("schema")!="ProofLaunchGTMRightMessageAdmissionDossierV2" or proposal.get("schema")!="ProofLaunchGTMRightMessageNamedReviewProposalV2": raise GTMRightMessageCandidateAdmissionError("RightMessage admission inputs use an unexpected schema")
    if proposal.get("source_unified_review_ledger_sha256")!=ledger.get("content_sha256") or proposal.get("source_admission_dossier_sha256")!=dossier.get("content_sha256"): raise GTMRightMessageCandidateAdmissionError("RightMessage proposal lineage is stale")
    records=intake.get("records",[])
    if len(records)!=1: raise GTMRightMessageCandidateAdmissionError("exactly one RightMessage review is required")
    review=records[0]
    if review.get("review_packet_id")!=proposal.get("review_packet_id") or review.get("decision")!="submit_for_admission_gate": raise GTMRightMessageCandidateAdmissionError("review did not submit the bound RightMessage packet")
    for field,key in (("field_bindings","field_bindings"),("cost_components","cost_components"),("exact_claim_bindings","exact_primary_claim_bindings")):
        if review.get(field)!=proposal.get(key): raise GTMRightMessageCandidateAdmissionError(f"RightMessage {field} drifted from the inspected proposal")
    if not all(review.get("gate_decisions",{}).values()): raise GTMRightMessageCandidateAdmissionError("one or more RightMessage named-review gates failed")
    if dossier.get("evidence_ready_gate_count")!=10 or dossier.get("blocking_gate_count")!=1 or dossier.get("gates",{}).get("named_human_exact_binding")!="pending_named_review": raise GTMRightMessageCandidateAdmissionError("RightMessage dossier is not at the strict 10/11 boundary")
    duplicate=dossier.get("duplicate_screen",{})
    if duplicate.get("exact_content_mirror_detected") or duplicate.get("additional_case_episode_collision_detected"): raise GTMRightMessageCandidateAdmissionError("RightMessage duplicate screen failed")
    sources={row["source_role"]:row for row in dossier.get("sources",[]) if row.get("capture_status")=="captured_and_bounded"}
    if len(sources)!=7 or sum(bool(row.get("independent")) for row in sources.values())<4: raise GTMRightMessageCandidateAdmissionError("RightMessage requires seven captures and four independent surfaces")
    classes={"founder_interview_2026":"public_community","independent_launch_profile":"independent_media","independent_financial_interview":"independent_media","cofounder_exit_account":"public_community","official_pricing":"official_company","independent_growth_reconstruction":"independent_media","independent_company_profile":"independent_media"}
    receipts=[{"source_url":row["source_url"],"source_class":classes[role],"access_method":"ordinary_public_page","captured_at":row["captured_at"],"content_sha256":row["source_content_sha256"]} for role,row in sources.items()]; hashes={role:row["source_content_sha256"] for role,row in sources.items()}; primary=hashes["founder_interview_2026"]; financial=hashes["independent_financial_interview"]; exit_hash=hashes["cofounder_exit_account"]
    costs={"paid_media":{"disclosure_status":"unknown","amount_usd":None,"evidence_receipt_sha256s":[primary,financial],"notes":"No complete paid-media ledger is public; owned and earned channels are not converted into zero spend."},"personnel":{"disclosure_status":"unknown","amount_usd":None,"evidence_receipt_sha256s":[primary,exit_hash],"notes":"A historical ten-person team and current solo-founder labor are explicit, but compensation is not itemized."},"tools":{"disclosure_status":"unknown","amount_usd":None,"evidence_receipt_sha256s":[primary,hashes["official_pricing"]],"notes":"Product, email, data, compliance and AI/MCP infrastructure totals are incomplete."},"creators":{"disclosure_status":"unknown","amount_usd":None,"evidence_receipt_sha256s":[primary,financial],"notes":"Founder email, guest-post, podcast and event labor is not separately priced."},"channel_fees":{"disclosure_status":"unknown","amount_usd":None,"evidence_receipt_sha256s":[financial],"notes":"Payment, affiliate, ESP/CRM integration and partner economics are incomplete."},"production":{"disclosure_status":"unknown","amount_usd":None,"evidence_receipt_sha256s":[primary,exit_hash,financial],"notes":"Original build, concierge setup, failure transition and full rebuild are not separately costed; the USD 20K monthly historical total is not falsely allocated."}}
    f=proposal["field_bindings"]; candidate={"case_id":CASE_ID,"status":"structured_candidate","subvertical_id":f["subvertical_ids"][0],"business_model":"b2b","company":f["company"],"product":f["product"],"campaign_or_motion":f["campaign_or_motion"],"primary_audience":f["primary_audience"],"observed_start":f["observed_start"],"observed_end":f["observed_end"],"episode_key":dossier["episode_key"],"company_scale":f["company_scale"],"lifecycle_state":f["lifecycle_state"],"budget_tier":f["budget_tier"],"recency_bucket":f["recency_bucket"],"outcome_type":f["outcome_type"],"quota_market":f["quota_market"],"platforms":["podcast_rss","owned_blog_newsletter","linkedin"],"mechanism_hypothesis":f["mechanism_summary"],"result_summary":f["result_summary"],"resource_scope":"Mixed-budget resources are source-bound through USD 500K-700K historical capital and a roughly USD 20K monthly total-expense snapshot; all six component totals remain unknown.","resource_costs":costs,"budget_quota_status":"source_bound","budget_classification_evidence_receipt_sha256s":[financial,exit_hash],"source_receipts":receipts,"review_binding":{"reviewer_name":review["reviewer_name"],"reviewed_at":review["reviewed_at"],"review_packet_id":review["review_packet_id"],"review_intake_sha256":_digest(intake)},"copy_or_voice_reuse_allowed":False,"quota_credit":1}
    for existing in existing_candidates:
        if existing.get("case_id")==CASE_ID or existing.get("episode_key")==candidate["episode_key"]: raise GTMRightMessageCandidateAdmissionError("RightMessage candidate or episode already exists")
    coverage=compile_case_evidence_funnel_coverage(build_case_evidence_funnel_standard(),[candidate],[],[],[])
    if coverage["global_funnel_counts"]["structured_candidates"]!=1: raise GTMRightMessageCandidateAdmissionError("RightMessage candidate failed CaseCandidateV2")
    payload={"schema":ADMISSION_SCHEMA,"source_sha256s":{"unified_review_ledger":ledger["content_sha256"],"named_review_intake":_digest(intake),"admission_dossier":dossier["content_sha256"],"named_review_proposal":proposal["content_sha256"]},"reviewer_name":review["reviewer_name"],"reviewed_at":review["reviewed_at"],"admitted_candidate_count":1,"formal_candidate_quota_credit":1,"candidate":candidate,"candidate_sha256":_digest(candidate),"automatic_external_action_allowed":False,"truth_boundary":"One structured-candidate credit only. The turnaround result remains founder-stated; funding recollections conflict, component costs are incomplete, and causality, transferability and blueprint readiness are unproven."}; payload["content_sha256"]=_digest(payload); return payload
def verify_rightmessage_candidate_admission(payload:Mapping[str,Any])->None:
    _seal(payload,"RightMessage admission")
    if payload.get("schema")!=ADMISSION_SCHEMA or payload.get("formal_candidate_quota_credit")!=1: raise GTMRightMessageCandidateAdmissionError("RightMessage admission aggregate is invalid")
    candidate=payload.get("candidate")
    if not isinstance(candidate,Mapping) or payload.get("candidate_sha256")!=_digest(candidate): raise GTMRightMessageCandidateAdmissionError("RightMessage candidate binding is invalid")
    if compile_case_evidence_funnel_coverage(build_case_evidence_funnel_standard(),[candidate],[],[],[])["global_funnel_counts"]["structured_candidates"]!=1: raise GTMRightMessageCandidateAdmissionError("RightMessage admission no longer passes CaseCandidateV2")
__all__=["ADMISSION_SCHEMA","CASE_ID","GTMRightMessageCandidateAdmissionError","compile_rightmessage_candidate_admission","verify_rightmessage_candidate_admission"]
